axlength="4" value="<?=e($p['ipi_code']??'')?>"></label><label class="settings-field">CST IBS/CBS<input name="ibs_cbs_cst" maxlength="4" value="<?=e($p['ibs_cbs_cst']??'')?>"></label><label class="settings-field">Classificação IBS/CBS<input name="ibs_cbs_classification" maxlength="20" value="<?=e($p['ibs_cbs_classification']??'')?>"></label></div><button class="button button--secondary">Salvar fiscal do produto</button></form><?php endforeach;?></section>
